  ('f_honey', null, 'Honey', '{"en":"Honey","de":"Honig","hr":"Med"}'::jsonb, 'na', 304, 0.3, 82.4, 0, 0.2, 1.42, null, 'builtin'),
  ('f_dark_chocolate', null, 'Dark chocolate 70%', '{"en":"Dark chocolate 70%","de":"Zartbitterschokolade 70%","hr":"Tamna čokolada 70%"}'::jsonb, 'na', 598, 7.8, 45.9, 42.6, 10.9, null, null, 'builtin'),
  ('f_milk_chocolate', null, 'Milk chocolate', '{"en":"Milk chocolate","de":"Milchschokolade","hr":"Mliječna čokolada"}'::jsonb, 'na', 535, 7.7, 59.4, 29.7, 3.4, null, null, 'builtin'),
  ('f_soy_sauce', null, 'Soy sauce', '{"en":"Soy sauce","de":"Sojasauce","hr":"Umak od soje"}'::jsonb, 'na', 53, 8.1, 4.9, 0.6, 0.8, 1.15, null, 'builtin'),
  ('f_ketchup', null, 'Ketchup', '{"en":"Ketchup","de":"Ketchup","hr":"Kečap"}'::jsonb, 'na', 101, 1, 27.4, 0.1, 0.3, 1.15, null, 'builtin'),
  ('f_mayo', null, 'Mayonnaise', '{"en":"Mayonnaise","de":"Mayonnaise","hr":"Majoneza"}'::jsonb, 'na', 680, 1, 0.6, 75, 0, 0.95, null, 'builtin'),
  ('f_coconut_milk', null, 'Coconut milk, canned', '{"en":"Coconut milk, canned","de":"Kokosmilch, Dose","hr":"Kokosovo mlijeko, konzerva"}'::jsonb, 'na', 197, 2.2, 2.8, 21.3, 0, 1, null, 'builtin')
insert into public.exercises (id, user_id, name, names, category, equipment_id, muscles, secondary, difficulty, instructions, instructions_i18n, tips, source) values
  ('ex_bench_press', null, 'Barbell Bench Press', '{"en":"Barbell Bench Press","de":"Bankdrücken (Langhantel)","hr":"Potisak s klupe (šipka)"}'::jsonb, 'chest', 'barbell', '["chest"]'::jsonb, '["triceps","front_delts"]'::jsonb, 2, 'Lie on the bench with your eyes under the bar and your feet flat on the floor. Lower the bar under control to mid-chest, then press it up until your arms are straight.', '{"en":"Lie on the bench with your eyes under the bar and your feet flat on the floor. Lower the bar under control to mid-chest, then press it up until your arms are straight.","de":"Lege dich so auf die Bank, dass die Augen unter der Stange sind, Füße fest am Boden. Senke die Stange kontrolliert zur Brustmitte und drücke sie nach oben, bis die Arme gestreckt sind.","hr":"Lezi na klupu tako da su ti oči ispod šipke, stopala čvrsto na podu. Kontrolirano spusti šipku do sredine prsa pa je potisni dok ne ispružiš ruke."}'::jsonb, '["spotter","shoulders"]'::jsonb, 'builtin'),
  ('ex_incline_db_press', null, 'Incline Dumbbell Press', '{"en":"Incline Dumbbell Press","de":"Schrägbankdrücken (Kurzhanteln)","hr":"Kosi potisak bučicama"}'::jsonb, 'chest', 'dumbbell', '["chest"]'::jsonb, '["front_delts","triceps"]'::jsonb, 2, 'Set the bench to about 30°. Press the dumbbells from chest height straight up, then lower them slowly until your elbows are slightly below shoulder level.', '{"en":"Set the bench to about 30°. Press the dumbbells from chest height straight up, then lower them slowly until your elbows are slightly below shoulder level.","de":"Stelle die Bank auf etwa 30°. Drücke die Hanteln von Brusthöhe gerade nach oben und senke sie langsam, bis die Ellbogen knapp unter Schulterhöhe sind.","hr":"Postavi klupu na oko 30°. Potisni bučice s visine prsa ravno gore pa ih polako spusti dok laktovi ne budu malo ispod razine ramena."}'::jsonb, '["shoulders","controlled"]'::jsonb, 'builtin'),
  ('ex_chest_press_machine', null, 'Chest Press Machine', '{"en":"Chest Press Machine","de":"Brustpresse (Maschine)","hr":"Potisak za prsa (sprava)"}'::jsonb, 'chest', 'machine', '["chest"]'::jsonb, '["triceps","front_delts"]'::jsonb, 1, 'Adjust the seat so the handles are at mid-chest height. Press the handles forward without locking your elbows hard, then return slowly.', '{"en":"Adjust the seat so the handles are at mid-chest height. Press the handles forward without locking your elbows hard, then return slowly.","de":"Stelle den Sitz so ein, dass die Griffe auf Brusthöhe sind. Drücke die Griffe nach vorn, ohne die Ellbogen hart durchzustrecken, und führe sie langsam zurück.","hr":"Namjesti sjedalo tako da su ručke u visini sredine prsa. Potisni ručke naprijed bez naglog zaključavanja laktova pa ih polako vrati."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_pec_deck', null, 'Pec Deck (Butterfly)', '{"en":"Pec Deck (Butterfly)","de":"Butterfly (Maschine)","hr":"Leptir (sprava)"}'::jsonb, 'chest', 'machine', '["chest"]'::jsonb, '["front_delts"]'::jsonb, 1, 'Sit upright with your back against the pad. Bring the arms together in front of your chest in a wide arc and open them slowly again.', '{"en":"Sit upright with your back against the pad. Bring the arms together in front of your chest in a wide arc and open them slowly again.","de":"Sitze aufrecht mit dem Rücken am Polster. Führe die Arme in einem weiten Bogen vor der Brust zusammen und öffne sie langsam wieder.","hr":"Sjedi uspravno s leđima na naslonu. Spoji ruke ispred prsa u širokom luku pa ih polako ponovno otvori."}'::jsonb, '["setup","range"]'::jsonb, 'builtin'),
  ('ex_cable_crossover', null, 'Cable Crossover', '{"en":"Cable Crossover","de":"Cable Crossover (Kabelzug)","hr":"Križanje sajli"}'::jsonb, 'chest', 'cable', '["chest"]'::jsonb, '["front_delts"]'::jsonb, 2, 'Stand between the pulleys with one foot forward. With slightly bent elbows, pull the handles together in front of your body and let them return slowly.', '{"en":"Stand between the pulleys with one foot forward. With slightly bent elbows, pull the handles together in front of your body and let them return slowly.","de":"Stehe im Ausfallschritt zwischen den Kabelzügen. Ziehe die Griffe mit leicht gebeugten Ellbogen vor dem Körper zusammen und lasse sie langsam zurück.","hr":"Stani između kolotura s jednom nogom naprijed. S blago savijenim laktovima spoji ručke ispred tijela i polako ih vrati."}'::jsonb, '["controlled","shoulders"]'::jsonb, 'builtin'),
  ('ex_push_up', null, 'Push-up', '{"en":"Push-up","de":"Liegestütz","hr":"Sklek"}'::jsonb, 'chest', 'bodyweight', '["chest"]'::jsonb, '["triceps","front_delts","abs"]'::jsonb, 1, 'Place your hands slightly wider than your shoulders and keep your body in one line. Lower your chest towards the floor and push back up. Kneeling makes it easier.', '{"en":"Place your hands slightly wider than your shoulders and keep your body in one line. Lower your chest towards the floor and push back up. Kneeling makes it easier.","de":"Hände etwas weiter als schulterbreit, der Körper bildet eine Linie. Senke die Brust Richtung Boden und drücke dich wieder hoch. Auf den Knien wird es leichter.","hr":"Dlanove postavi malo šire od ramena, tijelo drži u jednoj liniji. Spusti prsa prema podu i odgurni se natrag. Na koljenima je lakše."}'::jsonb, '["spine","range"]'::jsonb, 'builtin'),
  ('ex_chest_dips', null, 'Dips', '{"en":"Dips","de":"Dips (Barren)","hr":"Propadanja na razboju"}'::jsonb, 'chest', 'bodyweight', '["chest","triceps"]'::jsonb, '["front_delts"]'::jsonb, 3, 'Support yourself on the bars with straight arms. Lean slightly forward, lower yourself until your upper arms are about parallel to the floor, then press back up.', '{"en":"Support yourself on the bars with straight arms. Lean slightly forward, lower yourself until your upper arms are about parallel to the floor, then press back up.","de":"Stütze dich mit gestreckten Armen auf die Holme. Lehne dich leicht nach vorn, senke dich, bis die Oberarme etwa parallel zum Boden sind, und drücke dich hoch.","hr":"Osloni se na ruče ispruženim rukama. Blago se nagni naprijed, spusti se dok nadlaktice ne budu otprilike paralelne s podom pa se podigni."}'::jsonb, '["shoulders","range"]'::jsonb, 'builtin'),
  ('ex_lat_pulldown', null, 'Lat Pulldown', '{"en":"Lat Pulldown","de":"Latzug","hr":"Povlačenje na lat spravi"}'::jsonb, 'back', 'machine', '["lats"]'::jsonb, '["biceps","upper_back"]'::jsonb, 1, 'Fix your thighs under the pads and grip the bar wider than your shoulders. Pull the bar to your upper chest, elbows pointing down, and let it rise slowly.', '{"en":"Fix your thighs under the pads and grip the bar wider than your shoulders. Pull the bar to your upper chest, elbows pointing down, and let it rise slowly.","de":"Fixiere die Oberschenkel unter den Polstern und greife die Stange weiter als schulterbreit. Ziehe sie zur oberen Brust, Ellbogen nach unten, und lasse sie langsam hoch.","hr":"Učvrsti natkoljenice ispod jastuka i uhvati šipku šire od ramena. Povuci je do gornjeg dijela prsa, laktovi prema dolje, i polako je pusti gore."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_pull_up', null, 'Pull-up', '{"en":"Pull-up","de":"Klimmzug","hr":"Zgib"}'::jsonb, 'back', 'pullup_bar', '["lats"]'::jsonb, '["biceps","upper_back","forearms"]'::jsonb, 3, 'Hang from the bar with an overhand grip. Pull yourself up until your chin is above the bar, then lower yourself under control to straight arms.', '{"en":"Hang from the bar with an overhand grip. Pull yourself up until your chin is above the bar, then lower yourself under control to straight arms.","de":"Hänge im Obergriff an der Stange. Ziehe dich hoch, bis das Kinn über der Stange ist, und senke dich kontrolliert bis zu gestreckten Armen.","hr":"Objesi se o šipku nathvatom. Povuci se dok brada ne prijeđe šipku pa se kontrolirano spusti do ispruženih ruku."}'::jsonb, '["range","shoulders"]'::jsonb, 'builtin'),
  ('ex_assisted_pull_up', null, 'Assisted Pull-up Machine', '{"en":"Assisted Pull-up Machine","de":"Klimmzugmaschine (mit Unterstützung)","hr":"Zgibovi uz pomoć sprave"}'::jsonb, 'back', 'machine', '["lats"]'::jsonb, '["biceps","upper_back"]'::jsonb, 1, 'Choose a counterweight, kneel or stand on the pad and grip the handles. Pull yourself up, then lower slowly. More counterweight makes it easier.', '{"en":"Choose a counterweight, kneel or stand on the pad and grip the handles. Pull yourself up, then lower slowly. More counterweight makes it easier.","de":"Wähle ein Gegengewicht, knie oder stehe auf dem Polster und greife die Griffe. Ziehe dich hoch und senke dich langsam. Mehr Gegengewicht macht es leichter.","hr":"Odaberi protuuteg, klekni ili stani na jastuk i uhvati ručke. Povuci se gore pa se polako spusti. Veći protuuteg olakšava vježbu."}'::jsonb, '["setup","range"]'::jsonb, 'builtin'),
  ('ex_seated_row', null, 'Seated Cable Row', '{"en":"Seated Cable Row","de":"Rudern am Kabelzug (sitzend)","hr":"Veslanje na sajli (sjedeći)"}'::jsonb, 'back', 'cable', '["upper_back","lats"]'::jsonb, '["biceps","rear_delts"]'::jsonb, 1, 'Sit tall with slightly bent knees. Pull the handle to your lower ribs and squeeze your shoulder blades together, then extend your arms again.', '{"en":"Sit tall with slightly bent knees. Pull the handle to your lower ribs and squeeze your shoulder blades together, then extend your arms again.","de":"Sitze aufrecht mit leicht gebeugten Knien. Ziehe den Griff zu den unteren Rippen, führe die Schulterblätter zusammen und strecke die Arme wieder.","hr":"Sjedi uspravno s blago savijenim koljenima. Povuci ručku do donjih rebara, spoji lopatice pa ponovno ispruži ruke."}'::jsonb, '["spine","controlled"]'::jsonb, 'builtin'),
  ('ex_barbell_row', null, 'Bent-over Barbell Row', '{"en":"Bent-over Barbell Row","de":"Vorgebeugtes Rudern (Langhantel)","hr":"Veslanje u pretklonu (šipka)"}'::jsonb, 'back', 'barbell', '["upper_back","lats"]'::jsonb, '["biceps","lower_back","rear_delts"]'::jsonb, 3, 'Hinge at the hips with a flat back and slightly bent knees. Pull the bar to your lower chest or navel and lower it under control.', '{"en":"Hinge at the hips with a flat back and slightly bent knees. Pull the bar to your lower chest or navel and lower it under control.","de":"Beuge dich mit geradem Rücken und leicht gebeugten Knien aus der Hüfte vor. Ziehe die Stange zum unteren Brustkorb oder Bauchnabel und senke sie kontrolliert.","hr":"Nagni se iz kukova s ravnim leđima i blago savijenim koljenima. Povuci šipku prema donjem dijelu prsa ili pupku i kontrolirano je spusti."}'::jsonb, '["spine","warmup"]'::jsonb, 'builtin'),
  ('ex_db_row', null, 'One-arm Dumbbell Row', '{"en":"One-arm Dumbbell Row","de":"Einarmiges Kurzhantelrudern","hr":"Jednoručno veslanje bučicom"}'::jsonb, 'back', 'dumbbell', '["lats","upper_back"]'::jsonb, '["biceps","rear_delts"]'::jsonb, 1, 'Support one hand and knee on a bench with your back flat. Pull the dumbbell towards your hip, elbow close to the body, and lower it slowly.', '{"en":"Support one hand and knee on a bench with your back flat. Pull the dumbbell towards your hip, elbow close to the body, and lower it slowly.","de":"Stütze eine Hand und ein Knie auf der Bank ab, Rücken gerade. Ziehe die Hantel Richtung Hüfte, Ellbogen nah am Körper, und senke sie langsam.","hr":"Osloni jednu ruku i koljeno na klupu, leđa ravna. Povuci bučicu prema kuku, lakat uz tijelo, i polako je spusti."}'::jsonb, '["spine","controlled"]'::jsonb, 'builtin'),
  ('ex_deadlift', null, 'Deadlift', '{"en":"Deadlift","de":"Kreuzheben","hr":"Mrtvo dizanje"}'::jsonb, 'back', 'barbell', '["lower_back","glutes","hamstrings"]'::jsonb, '["upper_back","forearms","quads"]'::jsonb, 3, 'Stand with the bar over your mid-foot. Grip it, keep your back flat and chest up, and stand up by pushing the floor away. Lower the bar close to your legs.', '{"en":"Stand with the bar over your mid-foot. Grip it, keep your back flat and chest up, and stand up by pushing the floor away. Lower the bar close to your legs.","de":"Stehe mit der Stange über der Fußmitte. Greife sie, halte den Rücken gerade und die Brust oben, und richte dich auf, indem du den Boden wegdrückst. Senke die Stange nah an den Beinen.","hr":"Stani tako da je šipka iznad sredine stopala. Uhvati je, drži leđa ravna i prsa gore, pa se uspravi odgurujući pod. Spuštaj šipku uz noge."}'::jsonb, '["spine","warmup"]'::jsonb, 'builtin'),
  ('ex_back_extension', null, 'Back Extension', '{"en":"Back Extension","de":"Rückenstrecker (Hyperextension)","hr":"Ekstenzija leđa"}'::jsonb, 'back', 'bench', '["lower_back"]'::jsonb, '["glutes","hamstrings"]'::jsonb, 1, 'Position your hips on the pad. Bend forward from the hips with a straight back, then rise until your body forms one line. Do not overextend.', '{"en":"Position your hips on the pad. Bend forward from the hips with a straight back, then rise until your body forms one line. Do not overextend.","de":"Positioniere die Hüfte auf dem Polster. Beuge dich mit geradem Rücken aus der Hüfte vor und richte dich auf, bis der Körper eine Linie bildet. Nicht überstrecken.","hr":"Namjesti kukove na jastuk. Sagni se iz kukova s ravnim leđima pa se podigni dok tijelo ne bude u jednoj liniji. Ne pretjeruj s izvijanjem."}'::jsonb, '["spine","controlled"]'::jsonb, 'builtin'),
  ('ex_ohp', null, 'Overhead Press', '{"en":"Overhead Press","de":"Schulterdrücken (Langhantel)","hr":"Potisak iznad glave (šipka)"}'::jsonb, 'shoulders', 'barbell', '["front_delts","side_delts"]'::jsonb, '["triceps","upper_back","abs"]'::jsonb, 3, 'Hold the bar at collarbone height with your core tight. Press it straight overhead until your arms are extended, then lower it under control.', '{"en":"Hold the bar at collarbone height with your core tight. Press it straight overhead until your arms are extended, then lower it under control.","de":"Halte die Stange auf Schlüsselbeinhöhe, Rumpf fest. Drücke sie gerade über den Kopf, bis die Arme gestreckt sind, und senke sie kontrolliert.","hr":"Drži šipku u visini ključnih kostiju, trup čvrst. Potisni je ravno iznad glave do ispruženih ruku pa je kontrolirano spusti."}'::jsonb, '["spine","shoulders"]'::jsonb, 'builtin'),
  ('ex_db_shoulder_press', null, 'Dumbbell Shoulder Press', '{"en":"Dumbbell Shoulder Press","de":"Schulterdrücken (Kurzhanteln)","hr":"Potisak za ramena bučicama"}'::jsonb, 'shoulders', 'dumbbell', '["front_delts","side_delts"]'::jsonb, '["triceps"]'::jsonb, 2, 'Sit upright with the dumbbells at shoulder height. Press them overhead without arching your lower back and lower them slowly to ear level.', '{"en":"Sit upright with the dumbbells at shoulder height. Press them overhead without arching your lower back and lower them slowly to ear level.","de":"Sitze aufrecht, Hanteln auf Schulterhöhe. Drücke sie über den Kopf, ohne ins Hohlkreuz zu gehen, und senke sie langsam bis auf Ohrhöhe.","hr":"Sjedi uspravno s bučicama u visini ramena. Potisni ih iznad glave bez izvijanja donjeg dijela leđa i polako spusti do razine ušiju."}'::jsonb, '["shoulders","controlled"]'::jsonb, 'builtin'),
  ('ex_shoulder_press_machine', null, 'Shoulder Press Machine', '{"en":"Shoulder Press Machine","de":"Schulterpresse (Maschine)","hr":"Potisak za ramena (sprava)"}'::jsonb, 'shoulders', 'machine', '["front_delts","side_delts"]'::jsonb, '["triceps"]'::jsonb, 1, 'Adjust the seat so the handles start at shoulder height. Press upwards, stop just before your elbows lock and return slowly.', '{"en":"Adjust the seat so the handles start at shoulder height. Press upwards, stop just before your elbows lock and return slowly.","de":"Stelle den Sitz so ein, dass die Griffe auf Schulterhöhe starten. Drücke nach oben, stoppe kurz vor dem Durchstrecken und führe langsam zurück.","hr":"Namjesti sjedalo tako da ručke kreću iz visine ramena. Potisni prema gore, stani malo prije zaključavanja laktova i polako vrati."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_lateral_raise', null, 'Lateral Raise', '{"en":"Lateral Raise","de":"Seitheben","hr":"Odručenja bučicama"}'::jsonb, 'shoulders', 'dumbbell', '["side_delts"]'::jsonb, '["traps"]'::jsonb, 1, 'Stand with a dumbbell in each hand. Raise your slightly bent arms out to the sides up to shoulder height and lower them slowly. Use light weights.', '{"en":"Stand with a dumbbell in each hand. Raise your slightly bent arms out to the sides up to shoulder height and lower them slowly. Use light weights.","de":"Stehe mit je einer Hantel in der Hand. Hebe die leicht gebeugten Arme seitlich bis auf Schulterhöhe und senke sie langsam. Nimm leichte Gewichte.","hr":"Stani s bučicom u svakoj ruci. Podigni blago savijene ruke u stranu do visine ramena i polako ih spusti. Koristi lagane utege."}'::jsonb, '["controlled","shoulders"]'::jsonb, 'builtin'),
  ('ex_reverse_fly', null, 'Reverse Fly Machine', '{"en":"Reverse Fly Machine","de":"Reverse Butterfly (Maschine)","hr":"Obrnuti leptir (sprava)"}'::jsonb, 'shoulders', 'machine', '["rear_delts"]'::jsonb, '["upper_back","traps"]'::jsonb, 1, 'Sit facing the pad and hold the handles in front of you. Open your arms backwards in a wide arc until they are in line with your shoulders, then return.', '{"en":"Sit facing the pad and hold the handles in front of you. Open your arms backwards in a wide arc until they are in line with your shoulders, then return.","de":"Sitze mit der Brust zum Polster und halte die Griffe vor dir. Öffne die Arme in weitem Bogen nach hinten bis auf Schulterlinie und führe sie zurück.","hr":"Sjedi prsima prema naslonu i drži ručke ispred sebe. Otvori ruke unatrag u širokom luku do linije ramena pa ih vrati."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_face_pull', null, 'Face Pull', '{"en":"Face Pull","de":"Face Pull (Kabelzug)","hr":"Povlačenje užeta prema licu"}'::jsonb, 'shoulders', 'cable', '["rear_delts","upper_back"]'::jsonb, '["traps"]'::jsonb, 2, 'Set the rope at face height. Pull it towards your face, elbows high and hands apart, then extend your arms again slowly.', '{"en":"Set the rope at face height. Pull it towards your face, elbows high and hands apart, then extend your arms again slowly.","de":"Stelle das Seil auf Gesichtshöhe. Ziehe es zum Gesicht, Ellbogen hoch und Hände auseinander, und strecke die Arme langsam wieder.","hr":"Postavi uže u visinu lica. Povuci ga prema licu, laktovi visoko, a šake razmaknute, pa polako ispruži ruke."}'::jsonb, '["controlled","shoulders"]'::jsonb, 'builtin'),
  ('ex_front_raise', null, 'Front Raise', '{"en":"Front Raise","de":"Frontheben","hr":"Predručenja bučicama"}'::jsonb, 'shoulders', 'dumbbell', '["front_delts"]'::jsonb, '["side_delts"]'::jsonb, 1, 'Hold the dumbbells in front of your thighs. Raise them forwards to shoulder height with almost straight arms and lower them slowly without swinging.', '{"en":"Hold the dumbbells in front of your thighs. Raise them forwards to shoulder height with almost straight arms and lower them slowly without swinging.","de":"Halte die Hanteln vor den Oberschenkeln. Hebe sie mit fast gestreckten Armen nach vorn bis auf Schulterhöhe und senke sie langsam, ohne Schwung.","hr":"Drži bučice ispred natkoljenica. Podigni ih naprijed do visine ramena s gotovo ispruženim rukama i polako spusti, bez zamaha."}'::jsonb, '["controlled","spine"]'::jsonb, 'builtin'),
  ('ex_barbell_curl', null, 'Barbell Curl', '{"en":"Barbell Curl","de":"Langhantel-Curl","hr":"Pregib sa šipkom"}'::jsonb, 'arms', 'barbell', '["biceps"]'::jsonb, '["forearms"]'::jsonb, 1, 'Stand upright with the bar in an underhand grip. Curl it up to your shoulders with your elbows staying at your sides, then lower it slowly.', '{"en":"Stand upright with the bar in an underhand grip. Curl it up to your shoulders with your elbows staying at your sides, then lower it slowly.","de":"Stehe aufrecht, Stange im Untergriff. Beuge die Arme bis zu den Schultern, die Ellbogen bleiben am Körper, und senke langsam ab.","hr":"Stani uspravno, šipka u pothvatu. Savij ruke do ramena, laktovi ostaju uz tijelo, pa polako spusti."}'::jsonb, '["controlled","spine"]'::jsonb, 'builtin'),
  ('ex_db_curl', null, 'Dumbbell Curl', '{"en":"Dumbbell Curl","de":"Kurzhantel-Curl","hr":"Pregib s bučicama"}'::jsonb, 'arms', 'dumbbell', '["biceps"]'::jsonb, '["forearms"]'::jsonb, 1, 'Hold the dumbbells with your palms facing forward. Curl them up alternately or together without moving your upper arms, and lower them slowly.', '{"en":"Hold the dumbbells with your palms facing forward. Curl them up alternately or together without moving your upper arms, and lower them slowly.","de":"Halte die Hanteln mit den Handflächen nach vorn. Beuge die Arme abwechselnd oder gleichzeitig, ohne die Oberarme zu bewegen, und senke langsam ab.","hr":"Drži bučice s dlanovima prema naprijed. Savijaj ruke naizmjence ili zajedno bez pomicanja nadlaktica i polako spusti."}'::jsonb, '["controlled"]'::jsonb, 'builtin'),
  ('ex_hammer_curl', null, 'Hammer Curl', '{"en":"Hammer Curl","de":"Hammer-Curl","hr":"Čekić pregib"}'::jsonb, 'arms', 'dumbbell', '["biceps","forearms"]'::jsonb, '[]'::jsonb, 1, 'Hold the dumbbells with your palms facing each other. Curl them up to your shoulders in that neutral grip and lower them slowly.', '{"en":"Hold the dumbbells with your palms facing each other. Curl them up to your shoulders in that neutral grip and lower them slowly.","de":"Halte die Hanteln mit den Handflächen zueinander. Beuge die Arme in diesem neutralen Griff bis zu den Schultern und senke langsam ab.","hr":"Drži bučice s dlanovima okrenutima jedan prema drugome. Savij ruke do ramena u tom neutralnom hvatu i polako spusti."}'::jsonb, '["controlled"]'::jsonb, 'builtin'),
  ('ex_preacher_curl', null, 'Preacher Curl Machine', '{"en":"Preacher Curl Machine","de":"Bizepsmaschine (Scott-Curl)","hr":"Scott pregib (sprava)"}'::jsonb, 'arms', 'machine', '["biceps"]'::jsonb, '["forearms"]'::jsonb, 1, 'Rest your upper arms on the pad. Curl the handles towards your shoulders and lower them slowly until your arms are almost straight.', '{"en":"Rest your upper arms on the pad. Curl the handles towards your shoulders and lower them slowly until your arms are almost straight.","de":"Lege die Oberarme auf das Polster. Beuge die Griffe Richtung Schultern und senke sie langsam, bis die Arme fast gestreckt sind.","hr":"Osloni nadlaktice na jastuk. Savij ručke prema ramenima i polako ih spusti dok ruke ne budu gotovo ispružene."}'::jsonb, '["setup","range"]'::jsonb, 'builtin'),
  ('ex_triceps_pushdown', null, 'Triceps Pushdown', '{"en":"Triceps Pushdown","de":"Trizepsdrücken am Kabelzug","hr":"Potisak za triceps na sajli"}'::jsonb, 'arms', 'cable', '["triceps"]'::jsonb, '[]'::jsonb, 1, 'Stand in front of the high pulley with your elbows at your sides. Push the bar or rope down until your arms are straight and let it rise slowly.', '{"en":"Stand in front of the high pulley with your elbows at your sides. Push the bar or rope down until your arms are straight and let it rise slowly.","de":"Stehe vor dem oberen Kabelzug, Ellbogen am Körper. Drücke die Stange oder das Seil nach unten, bis die Arme gestreckt sind, und lasse es langsam hoch.","hr":"Stani ispred gornjeg kolotura, laktovi uz tijelo. Potisni šipku ili uže prema dolje do ispruženih ruku i polako pusti gore."}'::jsonb, '["controlled"]'::jsonb, 'builtin'),
  ('ex_overhead_triceps', null, 'Overhead Triceps Extension', '{"en":"Overhead Triceps Extension","de":"Trizepsstrecken über Kopf","hr":"Ekstenzija tricepsa iznad glave"}'::jsonb, 'arms', 'dumbbell', '["triceps"]'::jsonb, '[]'::jsonb, 2, 'Hold one dumbbell with both hands above your head. Lower it behind your head by bending your elbows, then extend your arms again.', '{"en":"Hold one dumbbell with both hands above your head. Lower it behind your head by bending your elbows, then extend your arms again.","de":"Halte eine Hantel mit beiden Händen über dem Kopf. Senke sie durch Beugen der Ellbogen hinter den Kopf und strecke die Arme wieder.","hr":"Drži jednu bučicu objema rukama iznad glave. Spusti je iza glave savijanjem laktova pa ponovno ispruži ruke."}'::jsonb, '["shoulders","controlled"]'::jsonb, 'builtin'),
  ('ex_skull_crusher', null, 'Lying Triceps Extension', '{"en":"Lying Triceps Extension","de":"Stirndrücken (liegend)","hr":"Čeoni potisak"}'::jsonb, 'arms', 'barbell', '["triceps"]'::jsonb, '[]'::jsonb, 2, 'Lie on a bench holding the bar above your chest. Bend only your elbows to lower the bar towards your forehead, then extend your arms.', '{"en":"Lie on a bench holding the bar above your chest. Bend only your elbows to lower the bar towards your forehead, then extend your arms.","de":"Liege auf der Bank und halte die Stange über der Brust. Beuge nur die Ellbogen und senke die Stange Richtung Stirn, dann strecke die Arme.","hr":"Lezi na klupu i drži šipku iznad prsa. Savijaj samo laktove i spusti šipku prema čelu pa ispruži ruke."}'::jsonb, '["controlled","spotter"]'::jsonb, 'builtin'),
  ('ex_squat', null, 'Barbell Back Squat', '{"en":"Barbell Back Squat","de":"Kniebeuge (Langhantel)","hr":"Čučanj sa šipkom"}'::jsonb, 'legs', 'barbell', '["quads","glutes"]'::jsonb, '["hamstrings","lower_back","abs"]'::jsonb, 3, 'Rest the bar on your upper back, feet about shoulder-width apart. Sit back and down with your chest up until your thighs are about parallel, then stand up.', '{"en":"Rest the bar on your upper back, feet about shoulder-width apart. Sit back and down with your chest up until your thighs are about parallel, then stand up.","de":"Lege die Stange auf den oberen Rücken, Füße etwa schulterbreit. Gehe mit aufrechter Brust nach hinten unten, bis die Oberschenkel etwa parallel sind, und stehe auf.","hr":"Položi šipku na gornji dio leđa, stopala u širini ramena. Spusti se unatrag i dolje s uspravnim prsima dok natkoljenice ne budu otprilike paralelne pa ustani."}'::jsonb, '["spine","knees","warmup"]'::jsonb, 'builtin'),
  ('ex_goblet_squat', null, 'Goblet Squat', '{"en":"Goblet Squat","de":"Goblet Squat","hr":"Goblet čučanj"}'::jsonb, 'legs', 'kettlebell', '["quads","glutes"]'::jsonb, '["abs"]'::jsonb, 1, 'Hold a kettlebell or dumbbell close to your chest. Squat down between your knees with an upright torso and stand back up.', '{"en":"Hold a kettlebell or dumbbell close to your chest. Squat down between your knees with an upright torso and stand back up.","de":"Halte eine Kettlebell oder Hantel nah an der Brust. Gehe mit aufrechtem Oberkörper zwischen den Knien in die Hocke und stehe wieder auf.","hr":"Drži girju ili bučicu uz prsa. Spusti se u čučanj između koljena s uspravnim trupom i ustani."}'::jsonb, '["knees","spine"]'::jsonb, 'builtin'),
  ('ex_leg_press', null, 'Leg Press', '{"en":"Leg Press","de":"Beinpresse","hr":"Nožna preša"}'::jsonb, 'legs', 'machine', '["quads","glutes"]'::jsonb, '["hamstrings"]'::jsonb, 1, 'Place your feet shoulder-width on the platform. Lower the weight until your knees are bent to about 90° and press it back without locking your knees.', '{"en":"Place your feet shoulder-width on the platform. Lower the weight until your knees are bent to about 90° and press it back without locking your knees.","de":"Stelle die Füße schulterbreit auf die Plattform. Senke das Gewicht, bis die Knie etwa 90° gebeugt sind, und drücke es zurück, ohne die Knie durchzustrecken.","hr":"Postavi stopala u širini ramena na platformu. Spusti uteg dok koljena ne budu savijena oko 90° i potisni natrag bez zaključavanja koljena."}'::jsonb, '["knees","setup"]'::jsonb, 'builtin'),
  ('ex_leg_extension', null, 'Leg Extension', '{"en":"Leg Extension","de":"Beinstrecker","hr":"Nožna ekstenzija"}'::jsonb, 'legs', 'machine', '["quads"]'::jsonb, '[]'::jsonb, 1, 'Align your knees with the machine''s pivot point. Extend your legs until they are almost straight, pause briefly and lower slowly.', '{"en":"Align your knees with the machine''s pivot point. Extend your legs until they are almost straight, pause briefly and lower slowly.","de":"Richte die Knie am Drehpunkt der Maschine aus. Strecke die Beine fast vollständig, halte kurz und senke langsam ab.","hr":"Poravnaj koljena s osi sprave. Ispruži noge gotovo do kraja, kratko zadrži i polako spusti."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_leg_curl', null, 'Leg Curl', '{"en":"Leg Curl","de":"Beinbeuger","hr":"Nožni pregib"}'::jsonb, 'legs', 'machine', '["hamstrings"]'::jsonb, '["calves"]'::jsonb, 1, 'Place the pad just above your heels. Bend your knees to pull the pad towards your glutes and return slowly without lifting your hips.', '{"en":"Place the pad just above your heels. Bend your knees to pull the pad towards your glutes and return slowly without lifting your hips.","de":"Platziere das Polster knapp über den Fersen. Beuge die Knie und ziehe das Polster Richtung Gesäß, dann langsam zurück, ohne die Hüfte anzuheben.","hr":"Postavi jastuk malo iznad peta. Savij koljena i povuci jastuk prema stražnjici pa polako vrati bez podizanja kukova."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_rdl', null, 'Romanian Deadlift', '{"en":"Romanian Deadlift","de":"Rumänisches Kreuzheben","hr":"Rumunjsko mrtvo dizanje"}'::jsonb, 'legs', 'barbell', '["hamstrings","glutes"]'::jsonb, '["lower_back"]'::jsonb, 2, 'Stand holding the bar with slightly bent knees. Push your hips back and slide the bar down your thighs with a flat back, then stand up by driving the hips forward.', '{"en":"Stand holding the bar with slightly bent knees. Push your hips back and slide the bar down your thighs with a flat back, then stand up by driving the hips forward.","de":"Stehe mit der Stange, Knie leicht gebeugt. Schiebe die Hüfte nach hinten und führe die Stange mit geradem Rücken an den Oberschenkeln entlang, dann Hüfte nach vorn.","hr":"Stani sa šipkom, koljena blago savijena. Gurni kukove unatrag i spuštaj šipku niz natkoljenice s ravnim leđima pa se uspravi guranjem kukova naprijed."}'::jsonb, '["spine","controlled"]'::jsonb, 'builtin'),
  ('ex_lunge', null, 'Lunge', '{"en":"Lunge","de":"Ausfallschritt","hr":"Iskorak"}'::jsonb, 'legs', 'dumbbell', '["quads","glutes"]'::jsonb, '["hamstrings"]'::jsonb, 2, 'Take a long step forward and lower your back knee towards the floor. Push off the front foot to return and switch sides.', '{"en":"Take a long step forward and lower your back knee towards the floor. Push off the front foot to return and switch sides.","de":"Mache einen großen Schritt nach vorn und senke das hintere Knie Richtung Boden. Drücke dich über den vorderen Fuß zurück und wechsle die Seite.","hr":"Napravi dug korak naprijed i spusti stražnje koljeno prema podu. Odgurni se prednjom nogom natrag i promijeni stranu."}'::jsonb, '["knees","spine"]'::jsonb, 'builtin'),
  ('ex_bulgarian_split_squat', null, 'Bulgarian Split Squat', '{"en":"Bulgarian Split Squat","de":"Bulgarische Kniebeuge","hr":"Bugarski čučanj"}'::jsonb, 'legs', 'dumbbell', '["quads","glutes"]'::jsonb, '["hamstrings"]'::jsonb, 3, 'Rest your back foot on a bench behind you. Lower yourself on the front leg until the thigh is about parallel to the floor and press back up.', '{"en":"Rest your back foot on a bench behind you. Lower yourself on the front leg until the thigh is about parallel to the floor and press back up.","de":"Lege den hinteren Fuß auf eine Bank. Senke dich auf dem vorderen Bein, bis der Oberschenkel etwa parallel zum Boden ist, und drücke dich hoch.","hr":"Položi stražnje stopalo na klupu iza sebe. Spusti se na prednjoj nozi dok natkoljenica ne bude otprilike paralelna s podom i podigni se."}'::jsonb, '["knees","controlled"]'::jsonb, 'builtin'),
  ('ex_hip_thrust', null, 'Hip Thrust', '{"en":"Hip Thrust","de":"Hip Thrust","hr":"Potisak kukovima"}'::jsonb, 'legs', 'barbell', '["glutes"]'::jsonb, '["hamstrings"]'::jsonb, 2, 'Lean your upper back against a bench with the bar over your hips. Drive your hips up until your body is level from shoulders to knees, then lower.', '{"en":"Lean your upper back against a bench with the bar over your hips. Drive your hips up until your body is level from shoulders to knees, then lower.","de":"Lehne den oberen Rücken an eine Bank, Stange über der Hüfte. Drücke die Hüfte hoch, bis Schultern und Knie eine Linie bilden, und senke ab.","hr":"Osloni gornji dio leđa na klupu, šipka preko kukova. Podigni kukove dok tijelo ne bude u ravnini od ramena do koljena pa spusti."}'::jsonb, '["spine","controlled"]'::jsonb, 'builtin'),
  ('ex_calf_raise', null, 'Calf Raise', '{"en":"Calf Raise","de":"Wadenheben","hr":"Podizanje na prste"}'::jsonb, 'legs', 'machine', '["calves"]'::jsonb, '[]'::jsonb, 1, 'Stand with the balls of your feet on the edge of the platform. Rise onto your toes as high as you can and lower your heels slowly below the edge.', '{"en":"Stand with the balls of your feet on the edge of the platform. Rise onto your toes as high as you can and lower your heels slowly below the edge.","de":"Stehe mit den Fußballen auf der Kante der Plattform. Hebe dich so hoch wie möglich auf die Zehen und senke die Fersen langsam unter die Kante.","hr":"Stani prednjim dijelom stopala na rub platforme. Podigni se na prste što više možeš i polako spusti pete ispod ruba."}'::jsonb, '["range","controlled"]'::jsonb, 'builtin'),
  ('ex_adductor', null, 'Adductor Machine', '{"en":"Adductor Machine","de":"Adduktorenmaschine","hr":"Sprava za aduktore"}'::jsonb, 'legs', 'machine', '["adductors"]'::jsonb, '[]'::jsonb, 1, 'Sit with the pads on the inside of your knees. Press your legs together, pause briefly and open them slowly to a comfortable stretch.', '{"en":"Sit with the pads on the inside of your knees. Press your legs together, pause briefly and open them slowly to a comfortable stretch.","de":"Sitze mit den Polstern an der Innenseite der Knie. Drücke die Beine zusammen, halte kurz und öffne sie langsam bis zu einer angenehmen Dehnung.","hr":"Sjedi s jastucima na unutarnjoj strani koljena. Stisni noge, kratko zadrži i polako ih otvori do ugodnog istezanja."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_abductor', null, 'Abductor Machine', '{"en":"Abductor Machine","de":"Abduktorenmaschine","hr":"Sprava za abduktore"}'::jsonb, 'legs', 'machine', '["abductors"]'::jsonb, '["glutes"]'::jsonb, 1, 'Sit with the pads on the outside of your knees. Press your legs apart, pause briefly and bring them back together slowly.', '{"en":"Sit with the pads on the outside of your knees. Press your legs apart, pause briefly and bring them back together slowly.","de":"Sitze mit den Polstern an der Außenseite der Knie. Drücke die Beine auseinander, halte kurz und führe sie langsam zusammen.","hr":"Sjedi s jastucima na vanjskoj strani koljena. Razmakni noge, kratko zadrži i polako ih spoji."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_plank', null, 'Plank', '{"en":"Plank","de":"Unterarmstütz (Plank)","hr":"Plank (izdržaj)"}'::jsonb, 'core', 'mat', '["abs"]'::jsonb, '["obliques","lower_back"]'::jsonb, 1, 'Support yourself on your forearms and toes. Keep your body in a straight line, tense your abs and glutes and breathe calmly. Enter seconds as reps.', '{"en":"Support yourself on your forearms and toes. Keep your body in a straight line, tense your abs and glutes and breathe calmly. Enter seconds as reps.","de":"Stütze dich auf Unterarme und Zehen. Halte den Körper in einer geraden Linie, spanne Bauch und Gesäß an und atme ruhig. Trage Sekunden als Wiederholungen ein.","hr":"Osloni se na podlaktice i prste. Drži tijelo u ravnoj liniji, napni trbuh i stražnjicu i diši mirno. Sekunde upiši kao ponavljanja."}'::jsonb, '["spine","breathe"]'::jsonb, 'builtin'),
  ('ex_side_plank', null, 'Side Plank', '{"en":"Side Plank","de":"Seitstütz","hr":"Bočni plank"}'::jsonb, 'core', 'mat', '["obliques"]'::jsonb, '["abs"]'::jsonb, 2, 'Lie on your side and support yourself on one forearm. Lift your hips until your body forms a straight line and hold. Switch sides.', '{"en":"Lie on your side and support yourself on one forearm. Lift your hips until your body forms a straight line and hold. Switch sides.","de":"Liege auf der Seite und stütze dich auf einen Unterarm. Hebe die Hüfte, bis der Körper eine gerade Linie bildet, und halte. Seite wechseln.","hr":"Lezi na bok i osloni se na jednu podlakticu. Podigni kukove dok tijelo ne bude u ravnoj liniji i zadrži. Promijeni stranu."}'::jsonb, '["spine","breathe"]'::jsonb, 'builtin'),
  ('ex_crunch', null, 'Crunch', '{"en":"Crunch","de":"Crunch","hr":"Trbušnjak (crunch)"}'::jsonb, 'core', 'mat', '["abs"]'::jsonb, '[]'::jsonb, 1, 'Lie on your back with bent knees. Curl your shoulder blades off the floor by tensing your abs, without pulling on your neck, and lower slowly.', '{"en":"Lie on your back with bent knees. Curl your shoulder blades off the floor by tensing your abs, without pulling on your neck, and lower slowly.","de":"Liege auf dem Rücken, Knie gebeugt. Hebe die Schulterblätter durch Anspannen des Bauchs vom Boden, ohne am Nacken zu ziehen, und senke langsam ab.","hr":"Lezi na leđa sa savijenim koljenima. Odigni lopatice od poda napinjanjem trbuha, bez povlačenja vrata, i polako spusti."}'::jsonb, '["controlled","breathe"]'::jsonb, 'builtin'),
  ('ex_hanging_leg_raise', null, 'Hanging Leg Raise', '{"en":"Hanging Leg Raise","de":"Beinheben im Hang","hr":"Podizanje nogu u visu"}'::jsonb, 'core', 'pullup_bar', '["abs","hip_flexors"]'::jsonb, '["forearms"]'::jsonb, 3, 'Hang from the bar. Raise your legs (bent knees are easier) until your thighs are at least horizontal and lower them without swinging.', '{"en":"Hang from the bar. Raise your legs (bent knees are easier) until your thighs are at least horizontal and lower them without swinging.","de":"Hänge an der Stange. Hebe die Beine (gebeugt ist leichter), bis die Oberschenkel mindestens waagerecht sind, und senke sie ohne Schwung.","hr":"Objesi se o šipku. Podigni noge (savijena koljena su lakša) dok natkoljenice ne budu barem vodoravne i spusti bez njihanja."}'::jsonb, '["controlled","shoulders"]'::jsonb, 'builtin'),
  ('ex_cable_crunch', null, 'Cable Crunch', '{"en":"Cable Crunch","de":"Crunch am Kabelzug","hr":"Trbušnjak na sajli"}'::jsonb, 'core', 'cable', '["abs"]'::jsonb, '["obliques"]'::jsonb, 2, 'Kneel in front of the high pulley holding the rope beside your head. Round your back and bring your elbows towards your knees, then rise slowly.', '{"en":"Kneel in front of the high pulley holding the rope beside your head. Round your back and bring your elbows towards your knees, then rise slowly.","de":"Knie vor dem oberen Kabelzug, Seil neben dem Kopf. Runde den Rücken und führe die Ellbogen Richtung Knie, dann langsam aufrichten.","hr":"Klekni ispred gornjeg kolotura s užetom uz glavu. Zaobli leđa i privuci laktove prema koljenima pa se polako uspravi."}'::jsonb, '["controlled","spine"]'::jsonb, 'builtin'),
  ('ex_russian_twist', null, 'Russian Twist', '{"en":"Russian Twist","de":"Russian Twist","hr":"Ruski zasuk"}'::jsonb, 'core', 'mat', '["obliques"]'::jsonb, '["abs"]'::jsonb, 2, 'Sit with bent knees and lean back slightly with a straight back. Rotate your torso from side to side, optionally holding a weight.', '{"en":"Sit with bent knees and lean back slightly with a straight back. Rotate your torso from side to side, optionally holding a weight.","de":"Sitze mit gebeugten Knien und lehne dich mit geradem Rücken leicht zurück. Drehe den Oberkörper von Seite zu Seite, optional mit Gewicht.","hr":"Sjedi sa savijenim koljenima i blago se nagni unatrag s ravnim leđima. Rotiraj trup s jedne na drugu stranu, po želji s utegom."}'::jsonb, '["spine","controlled"]'::jsonb, 'builtin'),
  ('ex_ab_machine', null, 'Abdominal Crunch Machine', '{"en":"Abdominal Crunch Machine","de":"Bauchmaschine","hr":"Sprava za trbušnjake"}'::jsonb, 'core', 'machine', '["abs"]'::jsonb, '[]'::jsonb, 1, 'Sit down and hold the handles or pads. Curl your upper body forward using your abs and return slowly to the start.', '{"en":"Sit down and hold the handles or pads. Curl your upper body forward using your abs and return slowly to the start.","de":"Setze dich und greife die Griffe oder Polster. Rolle den Oberkörper mit der Bauchmuskulatur nach vorn ein und gehe langsam zurück.","hr":"Sjedni i uhvati ručke ili jastuke. Savij gornji dio tijela naprijed snagom trbuha i polako se vrati."}'::jsonb, '["setup","controlled"]'::jsonb, 'builtin'),
  ('ex_dead_bug', null, 'Dead Bug', '{"en":"Dead Bug","de":"Dead Bug (Käfer)","hr":"Mrtva buba"}'::jsonb, 'core', 'mat', '["abs"]'::jsonb, '["hip_flexors"]'::jsonb, 1, 'Lie on your back with arms up and knees bent at 90°. Lower the opposite arm and leg towards the floor while your lower back stays down. Alternate.', '{"en":"Lie on your back with arms up and knees bent at 90°. Lower the opposite arm and leg towards the floor while your lower back stays down. Alternate.","de":"Liege auf dem Rücken, Arme nach oben, Knie 90° gebeugt. Senke gegengleich Arm und Bein Richtung Boden, der untere Rücken bleibt am Boden. Abwechseln.","hr":"Lezi na leđa, ruke gore, koljena savijena pod 90°. Spuštaj suprotnu ruku i nogu prema podu dok donji dio leđa ostaje na podu. Izmjenjuj."}'::jsonb, '["spine","breathe"]'::jsonb, 'builtin'),
  ('ex_treadmill', null, 'Treadmill', '{"en":"Treadmill","de":"Laufband","hr":"Traka za trčanje"}'::jsonb, 'cardio', 'cardio_machine', '["heart","quads"]'::jsonb, '["calves","hamstrings","glutes"]'::jsonb, 1, 'Start at walking speed and attach the safety clip. Increase speed or incline gradually and slow down for a few minutes before stepping off. Enter minutes as reps.', '{"en":"Start at walking speed and attach the safety clip. Increase speed or incline gradually and slow down for a few minutes before stepping off. Enter minutes as reps.","de":"Starte im Gehtempo und befestige den Sicherheitsclip. Erhöhe Tempo oder Steigung schrittweise und laufe einige Minuten aus. Trage Minuten als Wiederholungen ein.","hr":"Kreni brzinom hoda i pričvrsti sigurnosnu kopču. Postupno povećavaj brzinu ili nagib i usporavaj nekoliko minuta prije silaska. Minute upiši kao ponavljanja."}'::jsonb, '["gradual","warmup"]'::jsonb, 'builtin'),
  ('ex_bike', null, 'Stationary Bike', '{"en":"Stationary Bike","de":"Fahrradergometer","hr":"Sobni bicikl"}'::jsonb, 'cardio', 'cardio_machine', '["heart","quads"]'::jsonb, '["hamstrings","calves","glutes"]'::jsonb, 1, 'Set the saddle so your knee stays slightly bent at the bottom of the pedal stroke. Pedal smoothly and adjust the resistance to your level.', '{"en":"Set the saddle so your knee stays slightly bent at the bottom of the pedal stroke. Pedal smoothly and adjust the resistance to your level.","de":"Stelle den Sattel so ein, dass das Knie am tiefsten Punkt leicht gebeugt bleibt. Tritt gleichmäßig und passe den Widerstand an dein Niveau an.","hr":"Namjesti sjedalo tako da koljeno ostane blago savijeno u najnižoj točki. Okreći pedale ravnomjerno i prilagodi otpor svojoj razini."}'::jsonb, '["setup","gradual"]'::jsonb, 'builtin'),
  ('ex_elliptical', null, 'Elliptical Trainer', '{"en":"Elliptical Trainer","de":"Crosstrainer","hr":"Eliptični trenažer"}'::jsonb, 'cardio', 'cardio_machine', '["heart","quads","glutes"]'::jsonb, '["hamstrings","calves"]'::jsonb, 1, 'Step on, hold the handles and move in a smooth, gliding stride. Stay upright and keep your whole foot on the pedal.', '{"en":"Step on, hold the handles and move in a smooth, gliding stride. Stay upright and keep your whole foot on the pedal.","de":"Steige auf, greife die Griffe und bewege dich in einem gleichmäßigen, gleitenden Schritt. Bleibe aufrecht und lasse den ganzen Fuß auf dem Pedal.","hr":"Stani na spravu, uhvati ručke i kreći se ujednačenim, kliznim korakom. Ostani uspravan i drži cijelo stopalo na pedali."}'::jsonb, '["gradual","spine"]'::jsonb, 'builtin'),
  ('ex_rower', null, 'Rowing Machine', '{"en":"Rowing Machine","de":"Rudergerät","hr":"Veslački ergometar"}'::jsonb, 'cardio', 'cardio_machine', '["heart","upper_back","quads"]'::jsonb, '["lats","biceps","glutes","hamstrings"]'::jsonb, 2, 'Push with your legs first, then lean back slightly and pull the handle to your lower ribs. Return in reverse order: arms, upper body, legs.', '{"en":"Push with your legs first, then lean back slightly and pull the handle to your lower ribs. Return in reverse order: arms, upper body, legs.","de":"Drücke zuerst mit den Beinen, lehne dich dann leicht zurück und ziehe den Griff zu den unteren Rippen. Zurück in umgekehrter Reihenfolge: Arme, Oberkörper, Beine.","hr":"Najprije se odgurni nogama, zatim se blago nagni unatrag i povuci ručku do donjih rebara. Vraćaj se obrnutim redom: ruke, trup, noge."}'::jsonb, '["spine","gradual"]'::jsonb, 'builtin'),
  ('ex_stair_climber', null, 'Stair Climber', '{"en":"Stair Climber","de":"Stepper (Treppensteiger)","hr":"Steper (stepenice)"}'::jsonb, 'cardio', 'cardio_machine', '["heart","glutes","quads"]'::jsonb, '["calves","hamstrings"]'::jsonb, 2, 'Step at an even pace and stand upright. Rest your hands lightly on the rails for balance only, without leaning on them.', '{"en":"Step at an even pace and stand upright. Rest your hands lightly on the rails for balance only, without leaning on them.","de":"Steige in gleichmäßigem Tempo und bleibe aufrecht. Lege die Hände nur leicht zur Balance auf die Griffe, ohne dich abzustützen.","hr":"Penji se ujednačenim tempom i stoj uspravno. Ruke samo lagano osloni na rukohvate radi ravnoteže, bez naslanjanja."}'::jsonb, '["gradual","spine"]'::jsonb, 'builtin'),
  ('ex_jump_rope', null, 'Jump Rope', '{"en":"Jump Rope","de":"Seilspringen","hr":"Preskakanje vijače"}'::jsonb, 'cardio', 'other', '["heart","calves"]'::jsonb, '["forearms","quads"]'::jsonb, 2, 'Turn the rope from your wrists and jump just high enough to clear it. Land softly on the balls of your feet with slightly bent knees.', '{"en":"Turn the rope from your wrists and jump just high enough to clear it. Land softly on the balls of your feet with slightly bent knees.","de":"Schwinge das Seil aus den Handgelenken und springe nur so hoch wie nötig. Lande weich auf den Fußballen mit leicht gebeugten Knien.","hr":"Vrti vijaču iz zglobova šaka i skači tek toliko da je preskočiš. Doskači meko na prednji dio stopala s blago savijenim koljenima."}'::jsonb, '["gradual","knees"]'::jsonb, 'builtin'),
  ('ex_cat_cow', null, 'Cat-Cow', '{"en":"Cat-Cow","de":"Katze-Kuh","hr":"Mačka-krava"}'::jsonb, 'mobility', 'mat', '["lower_back","upper_back"]'::jsonb, '["abs"]'::jsonb, 1, 'On all fours, slowly round your back upwards, then let it sink gently and lift your chest. Move in the rhythm of your breathing.', '{"en":"On all fours, slowly round your back upwards, then let it sink gently and lift your chest. Move in the rhythm of your breathing.","de":"Im Vierfüßlerstand den Rücken langsam nach oben runden, dann sanft absenken und die Brust heben. Bewege dich im Rhythmus der Atmung.","hr":"U četveronožnom položaju polako zaobli leđa prema gore pa ih nježno spusti i podigni prsa. Kreći se u ritmu disanja."}'::jsonb, '["breathe","pain"]'::jsonb, 'builtin'),
  ('ex_hip_flexor_stretch', null, 'Hip Flexor Stretch', '{"en":"Hip Flexor Stretch","de":"Hüftbeuger-Dehnung","hr":"Istezanje pregibača kuka"}'::jsonb, 'mobility', 'mat', '["hip_flexors"]'::jsonb, '["quads"]'::jsonb, 1, 'Kneel on one knee with the other foot in front. Push your hips gently forward with an upright torso and hold for 20–30 seconds per side.', '{"en":"Kneel on one knee with the other foot in front. Push your hips gently forward with an upright torso and hold for 20–30 seconds per side.","de":"Knie auf einem Knie, der andere Fuß steht vorn. Schiebe die Hüfte mit aufrechtem Oberkörper sanft nach vorn und halte 20–30 Sekunden pro Seite.","hr":"Klekni na jedno koljeno, drugo stopalo je naprijed. Nježno gurni kukove naprijed s uspravnim trupom i zadrži 20–30 sekundi po strani."}'::jsonb, '["breathe","pain"]'::jsonb, 'builtin'),
  ('ex_hamstring_stretch', null, 'Hamstring Stretch', '{"en":"Hamstring Stretch","de":"Dehnung der Oberschenkelrückseite","hr":"Istezanje stražnje lože"}'::jsonb, 'mobility', 'mat', '["hamstrings"]'::jsonb, '["calves"]'::jsonb, 1, 'Sit with one leg straight and the other bent. Lean forward from the hips with a long back until you feel a gentle stretch. Hold 20–30 seconds.', '{"en":"Sit with one leg straight and the other bent. Lean forward from the hips with a long back until you feel a gentle stretch. Hold 20–30 seconds.","de":"Sitze mit einem gestreckten und einem gebeugten Bein. Beuge dich mit langem Rücken aus der Hüfte vor, bis du eine sanfte Dehnung spürst. 20–30 Sekunden halten.","hr":"Sjedi s jednom ispruženom i jednom savijenom nogom. Nagni se iz kukova s izduženim leđima dok ne osjetiš blago istezanje. Zadrži 20–30 sekundi."}'::jsonb, '["breathe","pain"]'::jsonb, 'builtin'),
  ('ex_thoracic_rotation', null, 'Thoracic Rotation', '{"en":"Thoracic Rotation","de":"Brustwirbelsäulen-Rotation","hr":"Rotacija prsne kralježnice"}'::jsonb, 'mobility', 'mat', '["upper_back"]'::jsonb, '["obliques"]'::jsonb, 1, 'On all fours, place one hand behind your head. Rotate that elbow towards the ceiling and follow it with your eyes, then return. Switch sides.', '{"en":"On all fours, place one hand behind your head. Rotate that elbow towards the ceiling and follow it with your eyes, then return. Switch sides.","de":"Im Vierfüßlerstand eine Hand an den Hinterkopf legen. Drehe diesen Ellbogen zur Decke, der Blick folgt, und gehe zurück. Seite wechseln.","hr":"U četveronožnom položaju stavi jednu ruku iza glave. Zarotiraj taj lakat prema stropu, prati ga pogledom, pa se vrati. Promijeni stranu."}'::jsonb, '["breathe","controlled"]'::jsonb, 'builtin'),
  ('ex_band_pass_through', null, 'Band Shoulder Pass-through', '{"en":"Band Shoulder Pass-through","de":"Schulterkreisen mit Band","hr":"Prolaz trakom preko ramena"}'::jsonb, 'mobility', 'band', '["front_delts","rear_delts"]'::jsonb, '["chest","upper_back"]'::jsonb, 1, 'Hold a band or stick with a wide grip in front of your hips. With straight arms, lift it over your head and behind your back as far as comfortable, then return.', '{"en":"Hold a band or stick with a wide grip in front of your hips. With straight arms, lift it over your head and behind your back as far as comfortable, then return.","de":"Halte ein Band oder einen Stab weit gegriffen vor der Hüfte. Führe es mit gestreckten Armen über den Kopf hinter den Rücken, so weit es angenehm ist, und zurück.","hr":"Drži traku ili štap širokim hvatom ispred kukova. Ispruženim rukama prenesi je preko glave iza leđa koliko je ugodno pa vrati."}'::jsonb, '["shoulders","pain"]'::jsonb, 'builtin'),
  ('ex_childs_pose', null, 'Child''s Pose', '{"en":"Child''s Pose","de":"Kindhaltung","hr":"Položaj djeteta"}'::jsonb, 'mobility', 'mat', '["lower_back"]'::jsonb, '["lats","glutes"]'::jsonb, 1, 'Kneel, sit back on your heels and stretch your arms forward on the floor. Let your forehead rest and breathe deeply for 30–60 seconds.', '{"en":"Kneel, sit back on your heels and stretch your arms forward on the floor. Let your forehead rest and breathe deeply for 30–60 seconds.","de":"Knie dich hin, setze dich auf die Fersen und strecke die Arme nach vorn auf den Boden. Lege die Stirn ab und atme 30–60 Sekunden tief.","hr":"Klekni, sjedni na pete i ispruži ruke naprijed po podu. Osloni čelo i duboko diši 30–60 sekundi."}'::jsonb, '["breathe","pain"]'::jsonb, 'builtin'),
  ('ex_foam_roll', null, 'Foam Rolling', '{"en":"Foam Rolling","de":"Faszienrolle","hr":"Valjanje pjenastim valjkom"}'::jsonb, 'mobility', 'foam_roller', '["quads","upper_back"]'::jsonb, '["glutes","calves","lats"]'::jsonb, 1, 'Place the muscle on the roller and roll slowly back and forth for 30–60 seconds. Avoid rolling directly over joints or the lower spine.', '{"en":"Place the muscle on the roller and roll slowly back and forth for 30–60 seconds. Avoid rolling directly over joints or the lower spine.","de":"Lege den Muskel auf die Rolle und rolle 30–60 Sekunden langsam vor und zurück. Rolle nicht direkt über Gelenke oder die Lendenwirbelsäule.","hr":"Položi mišić na valjak i polako valjaj naprijed-natrag 30–60 sekundi. Ne valjaj izravno preko zglobova ni donjeg dijela kralježnice."}'::jsonb, '["pain","breathe"]'::jsonb, 'builtin')
